CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,email TEXT NOT NULL UNIQUE,password TEXT NOT NULL,name TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires INTEGER NOT NULL);
 CREATE TABLE IF NOT EXISTS properties(id INTEGER PRIMARY KEY AUTOINCREMENT,reference TEXT NOT NULL UNIQUE,payload TEXT NOT NULL,status TEXT NOT NULL,demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS inquiries(id INTEGER PRIMARY KEY AUTOINCREMENT,property_id INTEGER REFERENCES properties(id),name TEXT NOT NULL,phone TEXT NOT NULL,email TEXT NOT NULL,kind TEXT NOT NULL,requested_date TEXT NOT NULL,time_slot TEXT NOT NULL,message TEXT NOT NULL,consent_at TEXT NOT NULL,status TEXT NOT NULL,agent TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
 CREATE INDEX IF NOT EXISTS inquiries_status ON inquiries(status);
 CREATE INDEX IF NOT EXISTS properties_status ON properties(status);
